      if (o.brilho) { mt.emissive = new T.Color('#ffffff'); mt.emissiveMap = t; mt.emissiveIntensity = o.brilho; }
      if (o.transp) { mt.transparent = true; mt.depthWrite = false; }
      if (o.alfa) mt.alphaTest = o.alfa;
      if (o.lado) mt.side = T.DoubleSide;
