        const zb = cmat(256, 32, (x, W, H) => { zebra(x, W, H, 32); gasto(x, W, H, r, 200, .5); }, { rep: [Math.max(1, Math.round(w / 1.6)), 1], r: .7 });
        [d / 2 - .08, -d / 2 + .08].forEach(zz => g.add(malha(plano(w, .16, 0, .053, zz, -PI / 2), zb)));
        const geos = [];
