        const zc = d / 2 - .45;
        [-.45, .45].forEach(xx => { bx(g, .5, .38, .4, m('#c8c2ae', { r: .6 }), xx, .85, zc); const p = pl(g, .4, .28, tl, xx, 1.04, zc - .205); p.rotation.y = PI; });
        const cores = ['#ff3020', '#30ff60', '#ffd020'];
