        if (n) { g.add(juntar(bxs, cx)); if (o.filme !== false) bx(g, 1.16, .12 + Math.ceil(n / 4) * .42, 1.06, m('#e8f0f4', { op: .16, r: .1 }), 0, .1, 0); }
