        g.add(juntar(aros, metal('#b8bec4'))); if (tampas.length) g.add(juntar(tampas, metal('#c8ccd0')));
        const postes = [];
        [-w / 2 + .05, 0, w / 2 - .05].forEach(xx => postes.push(cil(.015, .015, .55, xx, .9, -.38, 6), ret(.03, .03, .34, xx, 1.43, -.24)));
