        g.add(juntar([cil(.015, .015, 1.0, 0, 0, 0, 6), ...[0, 1, 2].map(i => { const a = i / 3 * PI * 2; return cil(.012, .012, .45, Math.cos(a) * .17, 0, Math.sin(a) * .17, 5, Math.sin(a) * .8, 0, -Math.cos(a) * .8); })], metal('#3a3a3a')));
