          const rr = rng(k * 11 + 3), tons = [['#c99a86', '#b07a68', '#e0bfa8', '#9a6a58', '#d8b098'], ['#b88a74', '#a86e5c', '#d4ae98', '#8a5a4a', '#e4c4b0'], ['#d0a490', '#a07060', '#c48a76', '#e8cab6', '#90604e']][k];
