    const cil = (rt, rb, h, x, y, z, seg = 10, rx = 0, ry = 0, rz = 0, aberto = false) => { const g = rot(new T.CylinderGeometry(rt, rb, h, seg, 1, aberto), rx, ry, rz); g.translate(x, y + (rx || rz ? 0 : h / 2), z); return g; };
