      const ge = []; for (let i = 0; i < 6; i++) ge.push(bola(.05 + r() * .06, (r() - .5) * (cw - .2), .058, -.08 - r() * .45, 1, .08, 1.4, 7)); addJ(gv, ge, m('#f4f8fa', { op: .55, r: .2 }));
