      addJ(al, [caixa(.035, .3, .035, 0, 0, 0)], metal('#b8b8b0')); addJ(al, [cil(.03, .03, .16, 0, .3, 0, 10, 0, 0, PI / 2)], m('#a01818', { r: .5 }));
