      sf(g, .03, mv, -.14, y + .42, .21, 8); sf(g, .03, mr, -.14, y + .3, .21, 8);
      const pos = k => { al.rotation.x = .35 + (1 - k) * (PI - .7); };
      const fn = animador(pos, 3);
