        for (let i = 0; i < 4; i++) { const cx = r() * W, cy = r() * H, gr = x.createRadialGradient(cx, cy, 2, cx, cy, 40 + r() * 90); gr.addColorStop(0, 'rgba(110,80,40,.22)'); gr.addColorStop(1, 'rgba(110,80,40,0)'); x.fillStyle = gr; x.fillRect(0, 0, W, H); }
