      const lz = m('#ffffff', { unico: true, e: lim ? '#f4fbff' : '#e8e0b0', ei: 1.3 }); addJ(g, [caixa(.16, .03, .05, 0, h - .1, -.1)], lz);
      const dob = G(); dob.position.set(-w / 2, .08, d / 2); g.add(dob);
